"use client";

import { useEffect, useState } from "react";
import { UnicornScene } from "unicornstudio-react/next";

function CubeFallback() {
  return (
    <div className="cube-fallback" aria-hidden="true">
      <span />
      <span />
      <span />
    </div>
  );
}

export function CubeUnicorn() {
  const [canRender, setCanRender] = useState(false);

  useEffect(() => {
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => {
      const canvas = document.createElement("canvas");
      const hasWebGL = Boolean(
        canvas.getContext("webgl2") || canvas.getContext("webgl"),
      );
      setCanRender(hasWebGL && !reducedMotion.matches);
    };

    update();
    reducedMotion.addEventListener("change", update);
    return () => reducedMotion.removeEventListener("change", update);
  }, []);

  return (
    <div
      className="cube-stage"
      role="img"
      aria-label="Interactive three-dimensional cube"
    >
      {canRender ? (
        <UnicornScene
          jsonFilePath="/unicorn/cube-unicorn.json"
          sdkUrl="https://cdn.jsdelivr.net/gh/hiunicornstudio/unicornstudio.js@v2.2.5/dist/unicornStudio.umd.js"
          width="100%"
          height="100%"
          lazyLoad
          ariaLabel="Interactive three-dimensional cube"
          placeholder={<CubeFallback />}
          showPlaceholderOnError
          showPlaceholderWhileLoading
          onError={() => setCanRender(false)}
        />
      ) : (
        <CubeFallback />
      )}
    </div>
  );
}

"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(useGSAP, ScrollTrigger);

export function MotionRoot({ children }: { children: React.ReactNode }) {
  const scope = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

      gsap.utils.toArray<HTMLElement>("[data-project-media]").forEach((media) => {
        gsap.fromTo(
          media,
          { scale: 0.8, opacity: 0.2 },
          {
            scale: 1,
            opacity: 1,
            ease: "none",
            scrollTrigger: {
              trigger: media,
              start: "top 90%",
              end: "center 55%",
              scrub: true,
            },
          },
        );
      });

      gsap.utils.toArray<HTMLElement>("[data-stack-card]").forEach((card, index) => {
        ScrollTrigger.create({
          trigger: card,
          start: `top ${96 + index * 18}px`,
          endTrigger: "[data-stack]",
          end: "bottom bottom",
          pin: true,
          pinSpacing: false,
        });
      });
    },
    { scope },
  );

  return <div ref={scope}>{children}</div>;
}

