}

import Image from "next/image";
import { CubeUnicorn } from "@/components/cube-unicorn";
import { MotionRoot } from "@/components/portfolio-motion";
import {
  capabilities,
  projects,
  socialLinks,
  testimonials,
  type Project,
} from "@/lib/portfolio";

function SiteNav() {
  return (
    <header className="site-header">
      <nav className="site-nav" aria-label="Primary navigation">
        <a className="wordmark" href="#top" aria-label="Irfan Hossain, home">
          Irfan Hossain
        </a>
        <div className="nav-links">
          <a href="#work">Work</a>
          <a href="#about">About</a>
          <a href="#contact">Contact</a>
        </div>
        <details className="mobile-nav">
          <summary>Menu</summary>
          <div>
            <a href="#work">Work</a>
            <a href="#about">About</a>
            <a href="#contact">Contact</a>
          </div>
        </details>
        <a className="button button-primary nav-hire" href={socialLinks[0].href}>
          Hire Me
        </a>
      </nav>
    </header>
  );
}

function Hero() {
  return (
    <section className="hero" id="top" aria-labelledby="hero-title">
      <p className="eyebrow">Full-Stack Developer · Dhaka, Bangladesh</p>
      <h1 id="hero-title">I build digital products and physical systems.</h1>
      <div className="hero-actions">
        <a className="button button-primary" href={socialLinks[0].href}>
          Hire Me
        </a>
        <a className="button button-secondary" href="#work">
          Selected Work
        </a>
      </div>
      <CubeUnicorn />
    </section>
  );
}

function CapabilityMarquee() {
  return (
    <section className="capability-strip" aria-label="Fields of work">
      <div className="marquee-track">
        {[...capabilities, ...capabilities].map((capability, index) => (
          <span key={`${capability}-${index}`} aria-hidden={index >= capabilities.length}>
            {capability}
          </span>
        ))}
      </div>
    </section>
  );
}

function ProjectLinks({ project }: { project: Project }) {
  return (
    <div className="project-links">
      <a href={project.href} target="_blank" rel="noreferrer">
        Repository <span aria-hidden="true">↗</span>
      </a>
      {project.demo ? (
        <a href={project.demo} target="_blank" rel="noreferrer">
          Live product <span aria-hidden="true">↗</span>
        </a>
      ) : null}
    </div>
  );
}

function ProjectBento({ projects }: { projects: Project[] }) {
  return (
    <section className="chapter" id="work" aria-labelledby="work-title">
      <div className="section-heading">
        <p className="eyebrow">Selected work</p>
        <h2 id="work-title">Products built across screens and circuits.</h2>
      </div>
      <div className="project-bento grid grid-cols-1 md:grid-cols-12 md:grid-rows-2 grid-flow-dense">
        {projects.map((project) => (
          <article
            className={`project-card tone-${project.tone} ${project.gridClass}`}
            key={project.slug}
          >
            <a
              className="project-media media-link"
              href={project.demo ?? project.href}
              target="_blank"
              rel="noreferrer"
              aria-label={`View ${project.title}`}
            >
              <Image
                src={project.image}
                alt={project.imageAlt}
                fill
                sizes="(max-width: 767px) 100vw, 50vw"
                data-project-media
              />
            </a>
            <div className="project-copy">
              <p className="eyebrow">{project.field}</p>
              <h3>{project.title}</h3>
              <p>{project.summary}</p>
              <ProjectLinks project={project} />
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

function FieldStatement() {
  return (
    <section className="field-statement" id="about" aria-labelledby="about-title">
      <p className="eyebrow">From interface to hardware</p>
      <h2 id="about-title">
        I take ideas from screen{" "}
        <span className="inline-image">
          <Image src="/projects/bteb-flow.png" alt="" fill sizes="160px" />
        </span>{" "}
        to circuit{" "}
        <span className="inline-image">
          <Image src="/projects/soldering-station.jpg" alt="" fill sizes="160px" />
        </span>{" "}
        and build the systems between.
      </h2>
      <p className="field-copy">
        Full-Stack Developer building scalable software, intuitive experiences,
        embedded systems, and IoT products.
      </p>
    </section>
  );
}

function ProjectAccordion({ projects }: { projects: Project[] }) {
  return (
    <div className="project-accordion" aria-label="Explore projects by field">
      {projects.map((project, index) => (
        <details className={`accordion-item tone-${project.tone}`} key={project.slug} open={index === 0}>
          <summary>
            <span>{project.field}</span>
            <strong>{project.title}</strong>
          </summary>
          <div className="accordion-copy">
            <p>{project.summary}</p>
            <a href={project.href} target="_blank" rel="noreferrer">
              Explore project <span aria-hidden="true">↗</span>
            </a>
          </div>
        </details>
      ))}
    </div>
  );
}

function ProjectStack({ projects }: { projects: Project[] }) {
  return (
    <section className="chapter project-stories" aria-labelledby="stories-title">
      <div className="section-heading">
        <p className="eyebrow">How the work takes shape</p>
        <h2 id="stories-title">One practice, from product decisions to precise control.</h2>
      </div>
      <ProjectAccordion projects={projects} />
      <div className="project-stack" data-stack>
        {projects.map((project) => (
          <article className={`stack-card tone-${project.tone}`} data-stack-card key={project.slug}>
            <div className="stack-copy">
              <p className="eyebrow">{project.field}</p>
              <h3>{project.title}</h3>
              <p>{project.summary}</p>
              <ProjectLinks project={project} />
            </div>
            <div className="stack-media">
              <Image
                src={project.image}
                alt={project.imageAlt}
                fill
                sizes="(max-width: 767px) 100vw, 55vw"
                data-project-media
              />
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

function TestimonialStructure() {
  return testimonials.length ? <section aria-label="Testimonials" /> : null;
}

function ContactSection({ links }: { links: typeof socialLinks }) {
  return (
    <section className="contact-section" id="contact" aria-labelledby="contact-title">
      <p className="eyebrow">Available for internships and freelance projects.</p>
      <h2 id="contact-title">Have something worth building?</h2>
      <p>Let&apos;s make the product, system, or prototype real.</p>
      <a className="button button-primary" href={links[0].href}>
        Hire Me
      </a>
    </section>
  );
}

function SiteFooter({ links }: { links: typeof socialLinks }) {
  return (
    <footer className="site-footer">
      <div>
        <a className="footer-name" href="#top">Irfan Hossain</a>
        <p>Full-Stack Developer · Dhaka, Bangladesh</p>
      </div>
      <nav aria-label="Social links">
        {links.map((link) => (
          <a key={link.label} href={link.href} target={link.label === "Email" ? undefined : "_blank"} rel={link.label === "Email" ? undefined : "noreferrer"}>
            {link.label}
          </a>
        ))}
      </nav>
    </footer>
  );
}

export default function Home() {
  return (
    <MotionRoot>
      <main className="w-full max-w-full overflow-x-hidden">
        <SiteNav />
        <Hero />
        <CapabilityMarquee />
        <ProjectBento projects={projects} />
        <FieldStatement />
        <ProjectStack projects={projects} />
        <TestimonialStructure />
        <ContactSection links={socialLinks} />
        <SiteFooter links={socialLinks} />
      </main>
    </MotionRoot>
  );
}

@import "tailwindcss";

:root {
  --ink: #000000;
  --canvas: #ffffff;
  --surface-soft: #f3f3f3;
  --hairline: #e5e5e5;
  --block-lime: #c8f169;
  --block-lilac: #daccff;
  --block-cream: #f4efc6;
  --block-mint: #bdf3dc;
  --block-pink: #ffc7e8;
  --block-coral: #ff8f7e;
  --block-navy: #25244f;
}

@theme inline {
  --color-background: var(--canvas);
  --color-foreground: var(--ink);
  --font-sans: var(--font-outfit);
  --font-mono: var(--font-geist-mono);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 6rem;
}

body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-outfit), sans-serif;
  font-size: 18px;
  font-weight: 320;
  line-height: 1.45;
}

button,
a,
summary {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 4px;
}

.site-footer :focus-visible,
.tone-navy :focus-visible {
  outline-color: var(--canvas);
}

.site-header {
  position: relative;
  z-index: 20;
  background: var(--canvas);
  border-bottom: 1px solid var(--hairline);
}

.site-nav {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: min(100%, 1280px);
  min-height: 72px;
  margin: 0 auto;
  padding: 12px 32px;
}

.wordmark,
.footer-name {
  width: fit-content;
  font-size: 20px;
  font-weight: 540;
  letter-spacing: -0.2px;
}

.nav-links {
  display: flex;
  gap: 8px;
  align-items: center;
}

.nav-links a,
.mobile-nav a {
  min-height: 44px;
  padding: 9px 14px;
  font-size: 16px;
  font-weight: 480;
}

.nav-links a:hover,
.site-footer a:hover,
.project-links a:hover,
.accordion-copy a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.nav-hire {
  justify-self: end;
}

.mobile-nav {
  display: none;
  position: relative;
}

.mobile-nav summary {
  min-width: 44px;
  min-height: 44px;
  padding: 9px 12px;
  cursor: pointer;
  font-weight: 480;
  list-style: none;
}

.mobile-nav summary::-webkit-details-marker {
  display: none;
}

.mobile-nav > div {
  position: absolute;
  top: calc(100% + 13px);
  left: 50%;
  display: grid;
  min-width: 160px;
  padding: 12px;
  background: var(--canvas);
  border: 1px solid var(--hairline);
  border-radius: 24px;
  transform: translateX(-50%);
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 10px 22px;
  border-radius: 50px;
  font-size: 18px;
  font-weight: 480;
  line-height: 1.25;
  transition:
    transform 180ms ease,
    background-color 180ms ease;
}

.button:hover {
  transform: translateY(-2px);
}

.button-primary {
  background: var(--ink);
  color: var(--canvas);
}

.button-primary:hover {
  background: var(--block-navy);
}

.button-secondary {
  background: var(--canvas);
  color: var(--ink);
  border: 1px solid var(--ink);
}

.hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(100%, 1440px);
  min-height: calc(100svh - 72px);
  margin: 0 auto;
  padding: clamp(72px, 9vw, 128px) 32px 0;
  text-align: center;
}

.eyebrow {
  margin: 0;
  font-family: var(--font-geist-mono), monospace;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.hero h1 {
  max-width: 72rem;
  margin: 28px auto 0;
  font-size: clamp(3.25rem, 7vw, 6.5rem);
  font-weight: 340;
  line-height: 0.96;
  letter-spacing: -0.025em;
  text-wrap: balance;
}

.hero-actions {
  display: flex;
  gap: 12px;
  margin-top: 36px;
}

.cube-stage {
  position: relative;
  width: min(100%, 1120px);
  height: clamp(340px, 48vw, 610px);
  margin-top: 48px;
  overflow: hidden;
  background: var(--surface-soft);
  border-radius: 24px 24px 0 0;
  isolation: isolate;
}

.cube-stage > div {
  width: 100% !important;
  height: 100% !important;
}

.cube-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: var(--block-cream);
}

.cube-fallback span {
  position: absolute;
  width: clamp(90px, 16vw, 190px);
  aspect-ratio: 1;
  border: 3px solid var(--ink);
}

.cube-fallback span:nth-child(1) {
  background: var(--block-lilac);
  transform: translateY(-28%) rotate(30deg) skewX(-30deg) scaleY(0.86);
}

.cube-fallback span:nth-child(2) {
  background: var(--block-lime);
  transform: translate(-43%, 46%) skewY(30deg) scaleX(0.86);
}

.cube-fallback span:nth-child(3) {
  background: var(--block-coral);
  transform: translate(43%, 46%) skewY(-30deg) scaleX(0.86);
}

.capability-strip {
  overflow: hidden;
  background: var(--ink);
  color: var(--canvas);
  border-block: 1px solid var(--ink);
}

.marquee-track {
  display: flex;
  width: max-content;
  animation: marquee 24s linear infinite;
}

.marquee-track span {
  display: flex;
  align-items: center;
  min-height: 58px;
  padding: 0 32px;
  font-size: 18px;
  font-weight: 480;
  white-space: nowrap;
}

.marquee-track span::after {
  width: 6px;
  height: 6px;
  margin-left: 64px;
  background: var(--block-lime);
  border-radius: 50%;
  content: "";
}

@keyframes marquee {
  to {
    transform: translateX(-50%);
  }
}

.chapter {
  width: min(100%, 1344px);
  margin: 0 auto;
  padding: 176px 32px;
}

.section-heading {
  display: grid;
  grid-template-columns: minmax(160px, 0.35fr) 1fr;
  gap: 32px;
  align-items: start;
  margin-bottom: 64px;
}

.section-heading h2 {
  max-width: 900px;
  margin: 0;
  font-size: clamp(3rem, 6vw, 5.4rem);
  font-weight: 340;
  line-height: 1;
  letter-spacing: -0.022em;
  text-wrap: balance;
}

.project-bento {
  overflow: hidden;
  border-radius: 24px;
}

.project-card {
  display: grid;
  grid-template-rows: minmax(14rem, 1fr) auto;
  min-width: 0;
  min-height: 31rem;
  overflow: hidden;
  color: var(--ink);
  border: 0.5px solid var(--ink);
}

.project-media,
.stack-media {
  position: relative;
  display: block;
  min-height: 0;
  overflow: hidden;
  background: var(--surface-soft);
}

.project-media img,
.stack-media img {
  object-fit: cover;
  transition: transform 700ms ease-out;
}

.project-card:nth-child(-n + 2) .project-media img {
  object-position: center 12%;
}

.media-link:hover img {
  transform: scale(1.05) !important;
}

.project-copy {
  padding: 24px;
}

.project-copy h3,
.stack-copy h3 {
  margin: 10px 0 8px;
  font-size: clamp(1.7rem, 3vw, 2.6rem);
  font-weight: 540;
  line-height: 1.05;
  letter-spacing: -0.02em;
}

.project-copy > p:not(.eyebrow),
.stack-copy > p:not(.eyebrow) {
  max-width: 42ch;
  margin: 0;
  font-size: 17px;
}

.project-links {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 20px;
  margin-top: 20px;
}

.project-links a,
.accordion-copy a {
  min-height: 44px;
  padding-block: 9px;
  font-size: 15px;
  font-weight: 540;
}

.tone-lime {
  background: var(--block-lime);
}

.tone-lilac {
  background: var(--block-lilac);
}

.tone-coral {
  background: var(--block-coral);
}

.tone-navy {
  background: var(--block-navy);
  color: var(--canvas);
}

.field-statement {
  width: min(calc(100% - 64px), 1280px);
  margin: 0 auto;
  padding: clamp(72px, 10vw, 128px) clamp(28px, 7vw, 96px);
  overflow: hidden;
  background: var(--block-navy);
  color: var(--canvas);
  border-radius: 24px;
}

.field-statement h2 {
  max-width: 1100px;
  margin: 32px 0 0;
  font-size: clamp(3rem, 6.3vw, 5.6rem);
  font-weight: 340;
  line-height: 1.06;
  letter-spacing: -0.025em;
}

.inline-image {
  position: relative;
  display: inline-block;
  width: 1.85em;
  height: 0.72em;
  overflow: hidden;
  border-radius: 50px;
  vertical-align: 0.02em;
}

.inline-image img {
  object-fit: cover;
}

.inline-image:first-of-type img {
  object-position: center 14%;
}

.field-copy {
  max-width: 620px;
  margin: 56px 0 0 auto;
  font-size: 22px;
  font-weight: 330;
}

.project-stories {
  padding-bottom: 128px;
}

.project-accordion {
  display: flex;
  min-height: 360px;
  margin-bottom: 176px;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 24px;
}

.accordion-item {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  border-right: 1px solid var(--ink);
  transition: flex 500ms ease;
}

.accordion-item:last-child {
  border-right: 0;
}

.accordion-item[open] {
  flex: 2.6;
}

.accordion-item:not([open]):hover,
.accordion-item:not([open]):focus-within {
  flex: 1.35;
}

.accordion-item summary {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 190px;
  padding: 24px;
  cursor: pointer;
  list-style: none;
}

.accordion-item summary::-webkit-details-marker {
  display: none;
}

.accordion-item summary span {
  font-family: var(--font-geist-mono), monospace;
  font-size: 11px;
  letter-spacing: 0.6px;
  text-transform: uppercase;
}

.accordion-item summary strong {
  max-width: 14ch;
  font-size: clamp(1.35rem, 2.5vw, 2.2rem);
  font-weight: 540;
  line-height: 1.05;
}

.accordion-copy {
  max-width: 48ch;
  padding: 0 24px 24px;
}

.accordion-copy p {
  margin: 0 0 12px;
}

.project-stack {
  position: relative;
}

.stack-card {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  min-height: 72svh;
  margin-bottom: 128px;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 24px;
}

.stack-card:last-child {
  margin-bottom: 0;
}

.stack-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: clamp(28px, 5vw, 72px);
}

.stack-copy h3 {
  font-size: clamp(2.6rem, 5vw, 5rem);
}

.stack-media {
  margin: 24px;
  border-radius: 16px;
}

.contact-section {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  width: min(calc(100% - 64px), 1280px);
  min-height: 76svh;
  margin: 48px auto 176px;
  padding: clamp(48px, 9vw, 112px);
  background: var(--block-lime);
  border-radius: 24px;
}

.contact-section h2 {
  max-width: 900px;
  margin: 28px 0 20px;
  font-size: clamp(3.5rem, 7vw, 6.5rem);
  font-weight: 340;
  line-height: 0.96;
  letter-spacing: -0.025em;
}

.contact-section > p:not(.eyebrow) {
  margin: 0 0 36px;
  font-size: 22px;
}

.site-footer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  padding: 80px max(32px, calc((100vw - 1280px) / 2));
  background: var(--ink);
  color: var(--canvas);
}

.site-footer p {
  margin: 12px 0 0;
  font-size: 15px;
}

.site-footer nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px 24px;
}

.site-footer nav a {
  min-height: 44px;
  padding-block: 9px;
  font-size: 16px;
  font-weight: 480;
}

@media (min-width: 768px) {
  .project-bento {
    grid-template-rows: repeat(2, minmax(31rem, 1fr));
  }
}

@media (max-width: 959px) {
  .site-nav {
    grid-template-columns: 1fr auto auto;
    gap: 8px;
  }

  .nav-links {
    display: none;
  }

  .mobile-nav {
    display: block;
  }

  .section-heading {
    grid-template-columns: 1fr;
  }

  .project-accordion {
    min-height: 330px;
  }

  .accordion-item summary {
    padding: 18px;
  }

  .accordion-copy {
    padding-inline: 18px;
  }
}

@media (max-width: 767px) {
  html {
    scroll-padding-top: 5rem;
  }

  .site-nav {
    min-height: 64px;
    padding: 10px 18px;
  }

  .wordmark {
    font-size: 17px;
  }

  .nav-hire {
    min-height: 44px;
    padding: 8px 16px;
    font-size: 16px;
  }

  .hero {
    min-height: auto;
    padding: 80px 18px 0;
  }

  .hero h1 {
    margin-top: 22px;
    font-size: clamp(2.65rem, 13vw, 3.25rem);
    line-height: 0.98;
  }

  .hero-actions {
    width: 100%;
    margin-top: 30px;
  }

  .hero-actions .button {
    flex: 1;
    padding-inline: 14px;
  }

  .cube-stage {
    width: calc(100% + 36px);
    height: 360px;
    margin-top: 48px;
    border-radius: 0;
  }

  .chapter {
    padding: 112px 18px;
  }

  .section-heading {
    margin-bottom: 42px;
  }

  .section-heading h2 {
    font-size: clamp(2.7rem, 13vw, 4rem);
  }

  .project-bento {
    width: calc(100% + 36px);
    margin-left: -18px;
    border-radius: 0;
  }

  .project-card {
    min-height: 580px;
  }

  .field-statement,
  .contact-section {
    width: 100%;
    border-radius: 0;
  }

  .field-statement {
    padding: 88px 24px;
  }

  .field-statement h2 {
    font-size: clamp(2.65rem, 12vw, 4rem);
  }

  .field-copy {
    margin-top: 42px;
    font-size: 19px;
  }

  .project-accordion {
    display: block;
    min-height: 0;
    margin-bottom: 112px;
    border-radius: 0;
  }

  .accordion-item {
    border-right: 0;
    border-bottom: 1px solid var(--ink);
  }

  .accordion-item:last-child {
    border-bottom: 0;
  }

  .accordion-item summary {
    min-height: 136px;
  }

  .stack-card {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(330px, 52svh);
    min-height: 75svh;
    margin-bottom: 80px;
    border-radius: 0;
  }

  .stack-copy {
    padding: 34px 24px;
  }

  .stack-copy h3 {
    font-size: clamp(2.5rem, 13vw, 4rem);
  }

  .stack-media {
    margin: 0 14px 14px;
    border-radius: 12px;
  }

  .contact-section {
    min-height: 76svh;
    margin: 24px 0 112px;
    padding: 72px 24px;
  }

  .contact-section h2 {
    font-size: clamp(3.1rem, 15vw, 5rem);
  }

  .contact-section .button {
    width: 100%;
  }

  .site-footer {
    grid-template-columns: 1fr;
    padding: 64px 24px;
  }

  .site-footer nav {
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .wordmark {
    max-width: 72px;
    line-height: 1;
  }

  .mobile-nav summary {
    padding-inline: 6px;
  }

  .nav-hire {
    padding-inline: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .marquee-track {
    transform: none;
  }
}

